import { observer, useObserver } from "mobx-react-lite";
import SchemaQueryForm, { SchemaQueryFormProps } from "../QueryForm";
import SchemaTable, { SchemaTableProps } from '../Table';
import SchemaForm, { SchemaFormProps } from '../Form';
import SchemaView, { SchemaViewProps } from '../View';
import Store from './store';
import { forwardRef, HTMLProps, ReactNode, useCallback, useEffect, useImperativeHandle, useMemo, useState } from "react";
import { Typography, Card, Button, Modal, Form, Message, Tooltip, Link, Space, Radio, Grid, Dropdown, Menu, ModalProps } from '@arco-design/web-react';
import { schemaToJSON } from "@/utils/schema";
import OperationList, { OperationListProps } from "@/components/custom/OperationList";
import { assign } from "lodash";
import _ from 'lodash';
import { convertToTree } from "@/utils";
import Log, { LogProps } from './Log';
import { JSONSchemaCustom } from "..";
import { toJS } from "mobx";
import { IconDelete } from "@arco-design/web-react/icon";
import ajax from "@/utils/ajax";


export interface ApiFindParam {
    // 当前页码
    current: number,
    // 加载数量
    pageSize: number,
    // form 查询条件
    [key: string]: any
}

interface toolBarRenderValue {
    add: () => void;
}

type SchemaType = boolean | JSONSchemaCustom;
export interface AllSchema extends JSONSchemaCustom {
    post?: SchemaType;
    put?: SchemaType;
    table?: SchemaType;
    query?: SchemaType;
    properties?: Record<string, AllSchema>;
    items?: AllSchema | AllSchema[];
}
/**
 * schema 页面
 */
export interface SchemaPageProps extends HTMLProps<HTMLDivElement> {
    schema: AllSchema;
    schemForm?: Partial<SchemaFormProps>;
    schemaTable?: Partial<SchemaTableProps>;
    queryForm?: Partial<SchemaQueryFormProps>;
    schemaView?: Partial<SchemaViewProps>;
    queryFilterKeys?: string[];
    tableFilterKeys?: string[];
    formFilterKeys?: string[];
    eidtProps?: SchemaFormProps['eidtProps'];
    viewFilterKeys?: string[];
    // 是否开启多选
    rowSelection?: boolean;
    headerTitle?: string;
    getToolBarRender?: ({ add }: toolBarRenderValue) => React.ReactNode[];
    // 编辑新增默认为弹窗样式
    modalProps?: ModalProps;
    // 是否为多层级数据
    treeBool?: boolean;
    // 层级数据key
    treeConfig?: {
        // 当前数据表示 默认：id
        key: string,
        // 对应的上一个层级标识 默认：parentId
        parentKey: string,
        // 上级菜单不能选择自己
        errMsg?: string,
    },
    getOperationList?: (list: OperationListProps['list'], rowData: any) => OperationListProps['list'],
    operation?: {
        // 行内新增动态配置
        add: (item: any) => boolean;
        // 行内编辑动态配置
        edit: (item: any) => boolean;
        // 行内删除动态配置
        delete?: (item: any) => boolean;
        // 行内详情按钮动态配置
        detail?: (item: any) => boolean;
    },
    api?: {
        // table 表格获取列表数据
        find?: (param: ApiFindParam) => Promise<{
            list: any[],
            // 总条数，如果没有分页，则不需要进行管理
            total?: number,
        }>,
        // 获取rowIndex 想去信息
        getDetail?: (item: any) => Promise<any>,
        // 获取详情信息
        get?: (item: any) => Promise<any>,
        // getData?: (data: any) => any;
        // 修改get 原始数据
        getParams?: (item: any) => any | Promise<any>,
        // 新增数据
        post?: (form: any) => Promise<any>,
        /**
         * @name  更新数据
         * @param form 当前表格数据
         */
        put?: (form: any) => Promise<any>,
        // 删除数据
        del?: (item: any) => Promise<any>,
        // 日志信息
        log?: (item: any, param: ApiFindParam) => Promise<{ list: any[], total?: number }>,
    },
    logProps?: LogProps
}

export interface SchemaPageInstance {
    // 更新页面数据(list)
    reload: () => void;
    // 刷新并清空,页码也会重置，不包括表单
    reloadAndRest: () => void;
    // 重置到默认值，包括表单
    reset: () => void;
    // 获取table列表数据
    getTableData: () => any[];
    // 获取table列表已选择数据
    getTableSelectedRow: () => { keys: Array<string | number>, rows: any[] }
}

const assignSchema = (schema: AllSchema, key) => {
    if(schema.properties){
        const properties = { ...schema.properties };
        for (const prop in properties) {
            const value = properties[prop];
            if(key in value){   // 存在属性，需要修改
                if(typeof value[key] === 'object') {
                    properties[prop] = _.assign({}, properties[prop], value[key]);
                }else if(value[key] === false){
                    // 去除当前schema
                    delete properties[prop]; 
                }
            }
        }
        schema.properties = properties;
    }else if(schema.items){
        if(Array.isArray(schema.items)){
            schema.items = schema.items.map((o) => assignSchema(o, key));
        }else {
            assignSchema(schema.items, key);
        }
    }
    return schema;
}

function SchemaPage({
    schema,
    schemForm,
    schemaTable,
    queryForm,
    schemaView,
    rowSelection,
    queryFilterKeys,
    tableFilterKeys,
    formFilterKeys,
    eidtProps,
    viewFilterKeys,
    headerTitle,
    getToolBarRender,
    modalProps,
    api,
    treeBool,
    treeConfig,
    logProps,
    ...props
}: SchemaPageProps, ref){

    const [store] = useState(() => {
        return new Store(api);
    })

    const { postSchema, putSchema, tableSchema, querySchema } = useMemo(() => {
        return {
            postSchema: assignSchema({ ...schema }, 'post'),
            putSchema: assignSchema({ ...schema }, 'put'),
            tableSchema: assignSchema({ ...schema }, 'table'),
            querySchema: assignSchema({ ...schema }, 'query'),
        }
    },[schema])


    return useObserver(() => {

        const [queryFormRef] = queryForm?.form? [queryForm.form] : Form.useForm();
        const [values, setValues] = useState(() => schemaToJSON(postSchema) || {});
        const [form] = schemForm?.form? [schemForm.form] : Form.useForm();
        const { mode, setMode, visible, setVisible, viewVisible, setViewVisible } = store;


        const treeKeys = useMemo(() => {
            return assign({ key: 'id', parentKey: 'parentId' }, treeConfig);
        },[treeConfig])

        const tableData = useMemo(() => {
            if(treeBool){
                return convertToTree(toJS(store.list), treeKeys.key, treeKeys.parentKey);
            }
            return toJS(store.list);
        },[store.list, treeBool])

        useImperativeHandle(ref, () => ({
            // 更新页面数据
            // 刷新
            reload: () => {
                store.getTableData();
            },
            // 刷新并清空,页码也会重置，不包括表单
            reloadAndRest: () => { 
                store.resetPagination();
                store.getTableData();
            },
            // 重置到默认值，包括表单
            reset: () => {
                store.resetPagination();
                store.resetParams();
                queryFormRef.clearFields();
                store.getTableData();
            },
            // 获取table列表数据
            getTableData: () => {
                if(treeBool){
                    return convertToTree(toJS(store.list), treeKeys.key, treeKeys.parentKey);
                }
                return toJS(store.list);
            },
            // 获取table表已选择数据
            getTableSelectedRow:() => {
                const rowKey: any = schemaTable?.rowKey || 'id'
                return { 
                    keys: store.selectedRows.map((o) => o[rowKey]),
                    rows: store.selectedRows
                }
            }
                     
        }), [])


        const getOperationList = useCallback((item) => {
            const list: OperationListProps['list'] = [
                {
                    title: '新增',
                    key: 'add',
                    hidden: !treeBool || !api.post,
                    onClick: () => {
                        setMode('post');
                        setVisible(true);
                        let params = schemaToJSON(schema);
                        if(treeBool){
                            params[treeKeys.parentKey] = item[treeKeys.key]
                        }
                        setValues(params);
                    }
                },
                {
                    title: '编辑',
                    key: "edit",
                    hidden: !api.put,
                    onClick: () => {
                        return store.getDetail(item).then((data) => {
                            // console.log('getDetail', data);
                            setValues(data);
                            setMode('put');
                            setVisible(true);
                        })
                    }
                },
                {
                    title: '详情',
                    key: "view",
                    hidden: !api.getDetail,
                    onClick: () => {
                        return store.getDetail(item).then((data) => {
                            setViewVisible(true);
                            setValues(data);
                        })
                    }
                },
                {
                    title: "日志",
                    key: "log",
                    hidden: !api.log,
                    onClick: () => {
                        // 获取日志信息
                        store.openLogVisible(item);
                    }
                },
                {
                    title: '删除',
                    key: "del",
                    hidden: !api.del,
                    onClick: () => {
                        // 删除数据
                        return store.delApi(item).then(() => {
                            store.getTableData();
                        });
                    }
                }
            ]

            if(props.getOperationList){

                return props.getOperationList(list, item);
            }

            return list;
        },[api, treeBool])

        // 表单初始值
        const initialValues = useMemo(() => {
            // null 会被判断为有值，所以转为 undefined 使用
            let fields = { ...values };
            const keys = Object.keys(values);
            for (const k of keys) {
                if(values[k] === null) {
                    fields[k] = undefined;
                }
            }
            return fields;
        },[values])

        useEffect(() => {
            if(visible){
                form.clearFields();
                form.setFieldsValue(initialValues);
            }
        },[visible])

        // 制定表哥操作栏
        const toolBarRender = useMemo(() => {
            const add = () => {
                setMode('post');
                setVisible(true);
                // console.log('schemaToJSON', schemaToJSON(schema))
                setValues(schemaToJSON(postSchema))
            }
            if(getToolBarRender){
                const nodes = getToolBarRender({ add });
                return Array.isArray(nodes)? nodes : [nodes];
            }
            if(api.post){
                return [
                    <Button
                        type="primary"
                        onClick={add}
                    >
                        新增
                    </Button>,
                    // <Tooltip content="回收站">
                    //     <Button
                    //         onClick={() => {
                    //             ajax.get('/log/tableRecycled', {
                    //                 tablename: "Module",
                    //             }).then((res) => {

                    //             })
                    //         }}
                    //         icon={<IconDelete />}
                    //     ></Button>
                    // </Tooltip>
                ]
            }
            return [];
        },[schema])

        const tableProps = useMemo(() => {
            const params: Partial<SchemaTableProps> = {
            };
            if(rowSelection || schemaTable?.rowSelection){
                const rowKey: any= schemaTable.rowKey || 'id';
                params.rowSelection = {
                    selectedRowKeys: store.selectedRows.map((o) => o[rowKey]),
                    onChange: (_, rows) => {
                        store.setSelectedRows(rows);
                    },
                    ...schemaTable.rowSelection
                }
            }
            return params;
        },[schemaTable, rowSelection, store.selectedRows])

        return (
            <div className="h-full flex flex-col" {...props}>
                <SchemaQueryForm
                    tableSchema={querySchema}
                    form={queryFormRef}
                    // filterKeys={['source', 'name', 'category', 'display']}
                    onSubmit={(params) => {
                        // console.log('params', params)
                        store.params = params;
                        store.resetPagination();
                        return store.getTableData();
                    }}
                    filterKeys={queryFilterKeys}
                    {...queryForm}
                />
                <div className="p-4 bg-white grow flex flex-col">
                    <SchemaTable
                        loading={store.loading}
                        schema={tableSchema}
                        pagination={{
                            sizeCanChange: true,
                            showTotal: true,
                            current: store.pagination.page,
                            pageSize: store.pagination.size,
                            total: store.pagination.total,
                            onChange: (page,size) => {
                                store.setPagination({
                                    page,
                                    size
                                })
                                store.getTableData();
                            }
                        }}
                        data={tableData}
                        filterKeys={tableFilterKeys}
                        // filterKeys={['source', 'name', 'category', 'display', 'description', 'updatedAt']}
                        headerTitle={headerTitle}
                        toolBarRender={toolBarRender}
                        addColumns={[
                            {
                                title: '操作',
                                dataIndex: 'id',
                                fixed: "right",
                                width: 140,
                                render: (col, item) => {
                                    return (
                                        <div style={{ whiteSpace:'nowrap' }}>
                                            <OperationList
                                                list={getOperationList(item)}
                                                argumentList={[item]}
                                            />
                                        </div>
                                    )
                                }
                            }
                        ]}
                        {...schemaTable}
                        {...tableProps}
                    />
                </div>
                <Modal
                    visible={visible}
                    title={`${mode === 'put'? '编辑' : '新增'}${schema.title || ''}`}
                    style={{
                        width: 1000
                    }}
                    // confirmLoading={store.saveLoading}
                    onCancel={() => setVisible(false)}
                    onConfirm={async () => {
                        await form.validate().then((res) => {
                            // store.setSaveLoading(true);
                            if(mode === 'post'){
                                // 新增
                                return store.postApi(res)
                                .then((result) => {
                                    if(result !== false){
                                        setVisible(false);
                                        store.getTableData();
                                    }
                                })
                                .finally(() => {
                                    store.setSaveLoading(false);
                                });
                            }else {
                                // 更新
                                return store.putApi(res, values)
                                .then((result) => {
                                    if(result !== false){
                                        setVisible(false);
                                        store.getTableData();
                                    }
                                })
                                .finally(() => {
                                    store.setSaveLoading(false);
                                });
                            }
                        })
                    }}
                    unmountOnExit={treeBool}
                    {...modalProps}
                >
                    <SchemaForm
                        schema={mode === 'put'? putSchema : postSchema}
                        form={form}
                        eidtProps={eidtProps}
                        isEdit={mode == "put"}
                        // filterKeys={['source', 'name', 'category', 'display', 'platform', 'props', 'manufacturer', 'extraInfo', 'description']}
                        filterKeys={formFilterKeys}
                        initialValues={initialValues}
                        labelCol={{
                            style: { maxWidth: 120 }
                        }}
                        wrapperCol={{
                            style: { flex: '1 0 100px' }
                        }}
                        {...schemForm}
                    />
                </Modal>
                <Modal
                    visible={viewVisible}
                    onCancel={() => setViewVisible(false)}
                    title={`${schema.title || ""}详情`}
                    cancelText="关闭"
                    style={{
                        width: 1000
                    }}
                    footer={(cancelButtonNode: ReactNode, okButtonNode: ReactNode) => cancelButtonNode}
                    {...modalProps}
                >
                    <SchemaView
                        schema={schema}
                        values={values}
                        filterKeys={viewFilterKeys}
                    />
                </Modal>
                <Modal
                    title="日志记录"
                    visible={store.logVisible}
                    onCancel={() => {
                        store.closeLogVisible();
                    }}
                    style={{
                        width: 1100
                    }}
                    footer={false}
                >
                    {store.logVisible && (
                        <Log getTableData={store.getLogTableData} {...logProps} />
                    )}
                </Modal>
            </div>
        )
    })
}


export default forwardRef(SchemaPage);