import { Dropdown, Link, Menu, Space, SpaceProps } from "@arco-design/web-react";
import { IconMore } from "@arco-design/web-react/icon";
import { useMemo } from "react";

export interface OperationItemProps {
    title: string;
    key?: 'add' | "edit" | "view" | "log" | "del" | "copy";
    // 是否隐藏
    hidden?: boolean;
    // 点击事件
    onClick: (e: any, ...arg: any[]) => void;
}

export interface OperationListProps extends SpaceProps {
    list: OperationItemProps[];
    // 展示 多少条数
    maxCount?: number;
    // 参数列表，会传给 list[].onClick(arguments)
    argumentList?: any[];
}

const OperationList = ({ 
    list: ParamsList, 
    maxCount = 2,
    argumentList = [],
    ...props
}: OperationListProps ) => {

    const list = useMemo(() => {
        if(!Array.isArray(ParamsList)) return[];
        return ParamsList.filter((o) => !o.hidden);
    },[ParamsList])
    const listfilters = useMemo(() => {
        if(!Array.isArray(list)) return[];
        return list.filter((o, i) => {
            return i < maxCount;
        })
    },[list])

    const moreRender = useMemo(() => {
        const moreList = list.slice(maxCount);
        if(!moreList.length) return null;
        const children = moreList.map((o, i) => {
            return (
                <Menu.Item 
                    key={String(i)}
                    onClick={(e) => {
                        o.onClick.apply(this, [e, ...argumentList])
                    }}
                >{o.title}</Menu.Item>
            )
        })

        return (
            <Dropdown
                position="bottom"
                droplist={
                    <Menu>
                        {children}
                    </Menu>
                }
            >
                <Link><IconMore /></Link>
            </Dropdown> 
        )
    }, [list])

    return (
        <Space size="small" {...props}>
            {listfilters.map((o, i) => {
                return (
                    <Link key={i} onClick={(e) => {
                        o.onClick.apply(this, [e, ...argumentList])
                    }}>
                        {o.title}
                    </Link>
                )
            })}
            {moreRender}
        </Space>
    )
}

export default OperationList;