import { schemaToDescriptionsData } from './utils';
import { Descriptions, DescriptionsProps, Image } from '@arco-design/web-react';
import { ReactNode, useMemo } from 'react';

interface DataItem {
    key?: React.Key;
    label?: ReactNode;
    value?: ReactNode;
    span?: number;
    form?: string;
}
export interface SchemaViewProps extends DescriptionsProps {
    schema?: JSONSchema,
    filterKeys?: string[];
    cols?: number;  // 默认排列
    values?: Record<string, any>
}

export default ({
    schema,
    values,
    filterKeys,
    cols = 12,
    ...props
}: SchemaViewProps) => {

    const data: SchemaViewProps['data'] = useMemo(() => {
        let result = schemaToDescriptionsData(schema, values);
        if(filterKeys){
            result = result.filter((o) => filterKeys.includes(o.key))
        }
        for (const item of result) {
            switch(item.format){
                case 'image':
                    item.value = <Image width={80} src={item.value} />
                break;
            }
        }

        return result.map((o) => ({ ...o, span: o.span || cols }));
    },[schema, values])

    return (
        <Descriptions
            // title={schema.title}
            column={24}
            data={data}
            colon={"："}
            {...props}
        />
    )
}