import { observable, action, computed, makeObservable } from 'mobx';


class Store {
    // 默认展示层级 4/6 6/4 8/3 12/2
    @observable cols = 8;

    constructor() {
        makeObservable(this);
    }

    // 列表层级数量
    @computed get columnSpan(){
        return Math.floor(24/this.cols);
    }

    @observable isAll = false;

    @action
    setIsAll = (bool) => {
        this.isAll = bool;
    }
}

export default Store;