import { getUuid } from "@/utils";
import { JSONSchemaCustom } from "../interface";
import { JoinItem, ApiJsonProps } from "./interface";
import _ from 'lodash';

interface ConstructorProps {
    apijson: ApiJsonProps
    schema: JSONSchemaCustom;
    joins: JoinItem[];
}

interface TableProps extends JoinItem {
    isToTable?: boolean; // 是否为中间表
}

interface FieldProps {
    name: string; // 字段名称，对应数据表真实字段名
    tableName: string; // 当前字段所属表
}

class Store {

    schema: JSONSchemaCustom;
    apijson: ApiJsonProps;
    tables?: Record<string, TableProps> = {};
    fields?: Record<string, FieldProps> = {};
    joins: JoinItem[] = [];
    // 预写入查询条件
    params: {
        // 默认进行左查询
        join: string[],
        [x: string]: any
    } = { join: [] }

    constructor({ schema, joins, apijson }: ConstructorProps){
        this.schema = schema;
        this.joins = joins;
        this.apijson = apijson;
        if(apijson){
            this.initJoins(joins);
        }
    }

    /**
     * 参数查询
     */
    queryParams = (params: Record<string, any> = {}) => {
        const obj = {};
        const { properties = {} } = this.schema || {}
        for (const key in params) {
            const value = params[key];
            if(typeof value != "undefined" && value !== ''){
                const schema: JSONSchemaCustom = properties[key];
                if(schema){
                    // 没有 format 代表为最基础 input 输入，默认采用 link查询
                    switch(schema.format){
                        case "dateRange":
                        case "timeRange":
                        case "dateTime":
                        case "date":
                        case "time":
                            if(Array.isArray(value)){
                                obj[`${key}%`] = value;
                            }
                        break;
                        default:
                            const { enum: enumList } = schema;
                            if(enumList){
                                if(Array.isArray(value)){
                                    obj[`${key}[]`] = value;
                                }else {
                                    obj[`${key}`] = value;
                                }
                            }else if(typeof value == "string") {
                                obj[`${key}$`] = `%${value}%`
                            }else {
                                obj[key] = value;
                            }
                    }
                }else {
                    obj[key] = value;
                }
            }
        }
        return obj;
    }
    
    // 合并当前关联表
    initJoins = (joins: JoinItem[]) => {
        const obj = {};
        if(!joins) return obj;
        for (const join of joins) {
            const { columns, tableName, type, uniqueKey, relationKey, toTableName, toRelationKey } = join;
            this.tables[tableName] = join;
            this.tables[toTableName] = { isToTable: true, ...join };
            if(columns && ["One"].includes(type)){
                // 目前逻辑，一对一可以直接查询关联表数据
                columns.forEach((str) => {
                    const [a,b] = str.split(':');
                    obj[(b || a).trim()] = { name: a.trim(), tableName } as FieldProps;
                })
            }
        }
        this.fields = obj;
        this.initParams();
    }

    // 获取columns 餐素
    getColumns = (columns: string[]) => {
        return columns? columns.join(',') : undefined
    }


    // join 参数组合
    initParams = () => {
        const { tableName: TName, uniqueKey: UKey } = this.apijson;
        for (const join of this.joins) {
            const { 
                type, tableName, columns = [],
                uniqueKey, foreignKey, relationKey,
                toTableName, toForeignKey, toRelationKey,
                toTableKey = 'uid',
            } = join;
            switch(type){
                case "One":
                    this.params[tableName] = {
                        [`${foreignKey}@`]: `/${TName}/${relationKey}`,
                        "@column": this.getColumns(columns),
                    }
                    this.params.join.push(tableName);
                break;
                case "Many":
                    this.params[`${tableName}[]`] = {
                        [tableName]: {
                            [`${foreignKey}@`]: `${TName}[]/${TName}/${relationKey}`,
                            "@column": this.getColumns(columns),
                        }
                    }
                break;
                case "OneMany":
                    this.params[`${tableName}[]`] = {
                        [tableName]: {
                            [`${foreignKey}@`]: `${TName}[]/${TName}/${relationKey}`,
                            "@column": this.getColumns(columns),
                        }
                    }
                break;
                case "To":
                    this.params[`${toTableName}[]`] = {
                        [toTableName]: {
                            [`${toRelationKey}@`]: `${TName}[]/${TName}/${relationKey}`,
                            "@column": `${toTableKey},${toForeignKey},${toRelationKey}`
                        }
                    }
                break;
                case "ToOne":
                    this.params[toTableName] = {
                        [`${toRelationKey}@`]: `/${TName}/${relationKey}`,
                        "@column": `${toTableKey},${toForeignKey},${toRelationKey}`
                    }
                    this.params[tableName] = {
                        [`${foreignKey}@`]: `/${toTableName}/${toForeignKey}`,
                        "@column": this.getColumns(columns),
                    }
                    this.params.join.push(tableName, toTableName);
                break;
                case "ToMany":
                    this.params[`${toTableName}[]`] = {
                        join: `&/${tableName}`,
                        [toTableName]: {
                            [`${toRelationKey}@`]: `${TName}[]/${TName}/${relationKey}`,
                            "@column": `${toTableKey},${toForeignKey},${toRelationKey}`
                        },
                        [tableName]: {
                            [`${foreignKey}@`]: `/${toTableName}/${toForeignKey}`,
                            "@column": this.getColumns(columns),
                        },
                    }
                break;
                case "ToOneMany":
                    this.params[`${toTableName}[]`] = {
                        join: `&/${tableName}`,
                        [toTableName]: {
                            [`${toRelationKey}@`]: `${TName}[]/${TName}/${relationKey}`,
                            "@column": `${toTableKey},${toForeignKey},${toRelationKey}`
                        },
                        [tableName]: {
                            [`${foreignKey}@`]: `/${toTableName}/${toForeignKey}`,
                            "@column": this.getColumns(columns),
                        },
                    }
                break;

            }
        }
    }


    /**
     * 根据查询条件生成查询信息
     */
    getJoinsParams(params){
        const { join, ...joinParams } = this.params;
        const { tableName: TName, uniqueKey: UKey } = this.apijson;
        let joinNode = {}; // 需要进行联合查询
        // 组合查询参数
        let tparms = _.cloneDeep(joinParams);
        if(params){
            const keys = Object.keys(params);
            // console.log('object.keys', keys, this.fields, this.tables)
            for (const key of keys) {
                const value = params[key];
                if(this.fields[key]){
                    const { tableName, name } = this.fields[key];
                    if(!joinNode[tableName]) joinNode[tableName] = true;
                    // 如果是子表的查询条件，则将查询值写入到子表中
                    if(tparms[tableName]){
                        _.assign(
                            tparms[tableName],
                            this.queryParams({ [key]: value })
                        )
                    }
                    delete params[key];
                }else if(this.tables[key]){
                    const table = this.tables[key];
                    // 继续判断当前字段是否可表名一致（逻辑待完善）
                    const { type, toTableName, toForeignKey, toRelationKey } = table;
                    if(type === "ToMany" ){
                        if(Array.isArray(params[key]) && params[key].length){
                            joinNode[toTableName] = true;
                            tparms[`${toTableName}`] = {
                                [`${toRelationKey}@`]: `/${TName}/${UKey}`,
                                [`${toForeignKey}{}`]: params[key],
                                "@group": `${toRelationKey}`,
                                "@column": `${toRelationKey},${toForeignKey}`
                            }
                        }
                    }
                    delete params[key];
                }
            }
        }
        const joinList = [
            ...join.filter((k) => !joinNode[k]).map((k) => `</${k}`),
            ...Object.keys(joinNode).map((k) => `</${k}`)
        ]
        if(joinList.length){
            tparms['join'] = joinList.join(',')
        }
        
        return tparms;
    }


    /**
     * 根据参数生成 post ｜ put 接口
     * @param params 当前的数据
     * @param data 原表单数据
     */
    getJoinSave(params: any, data?: any){
        const { tableName: TName, uniqueKey: UKey } = this.apijson;
        const sparams = {};
        // 创建事务
        const bus: any = {};
        for (const key in params) {
            const value = params[key];
            const table = this.tables[key];
            if(table && table.isToTable){
                const { type, toTableName, toTableKey = "uid", toForeignKey, toRelationKey, relationKey } = table;
                if(["To", "ToMany", "ToOneMany"].includes(type)){
                    /**
                     * 远程多对多和一对多通过中间表进行数据关联，所以需要进行特殊处理
                     */
                    if(Array.isArray(value)){
                        // if(!params[UKey]){
                        //     // 新增数据不存在id， 要写入一个uuid
                        //     params[UKey] = getUuid();
                        // }
                        // 获取新的数据组
                        let values = value.map((id) => {
                            if(typeof id === "object") return id;
                            const item = {
                                [toForeignKey]: id,
                            }
                            if(params[UKey]){
                                item[toRelationKey] = params[UKey];
                            }else {
                                item[`${toRelationKey}@`] = `${TName}/${UKey}`;
                            }
                            return item;
                        })
                        /**
                         * 用来做差异化对比，多对多数据对比规则
                         * 1、过滤掉未修改的数据
                         * 2、查找被删除的数据
                         * 3、查找要新增的数据
                         */
                        if(!data){
                            // 没有原数据，新增数据全部保存
                            _.set(bus, ['post', `${toTableName}[]`], values)
                        }else {
                            let postList = [];
                            // 目前存在的数据
                            let result = values.filter((o) => {
                                // 数据存在说明未修改
                                let bool = data[toTableName].some((item) => {
                                    return item[toForeignKey] == o[toForeignKey];
                                })
                                if(!bool){
                                    // 对比发现不存在数据，需要新增
                                    postList.push(o); 
                                }
                                return bool;
                            }).map((o) => o[toForeignKey])
                            if(postList.length){
                                _.set(bus, ['post', `${toTableName}[]`], postList)
                            }
                            // console.log('result', relationKey, result, data);
                            // 获取要删除数据(并获取到要删除数据ids)
                            const delIds = data[toTableName].filter((o) => {
                                return !result.includes(o[toForeignKey]); 
                            }).map((o) => o[toTableKey])
                            if(delIds.length){
                                _.set(bus, ['delete',`${toTableName}`],{
                                    [`${toTableKey}{}`]: delIds
                                });
                            }
                        }
                        // 这边要更新删除逻辑
                    }
                }else if(type === "Many"){
                    sparams[`${key}[]`] = value;
                }else {
                    sparams[key] = value;
                }
                delete params[key];
            }
        }
        return {
            bus,
            sparams,
        };
    }
    


    data: any = null;
    /**
     * 根据get 获取FormData 参数
     */
    getData(params: any){
        this.data = _.cloneDeep(params);
        for (const key in params) {
            const value = params[key];
            const table = this.tables[key];
            if(table && table.isToTable){
                const { type, toTableName, toTableKey = "uid", toForeignKey, toRelationKey, relationKey } = table;
                if(["To", "ToMany", "ToOneMany"].includes(type)){
                    params[key] = params[key].map((o) => {
                        return o[toForeignKey];
                    })
                }
            }
        }
        return params;
    }
}


export default Store;